class Base {
public:
    virtual void foo();
    int a;
};

class Derived : public Base {
public:
    void foo() override;
    int b;
};

// Implementation notes:
// - Objects of Derived contain a pointer to the vtable for Derived.
// - Base class subobject is at the start of Derived object.
// - Constructor initializes vtable pointer and members.
// - Destructor calls are dispatched via vtable, enabling polymorphic cleanup.
